css:
.sl-footer-bento { font-family: var(--smartlearn-body-font, inherit); }
.sl-footer-bento .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-footer-bento .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-bento .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-bento.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-bento .sl-bg-card {
    background-color: var(--smartlearn-card-bg) !important;
    border: 1px solid var(--smartlearn-card-border) !important;
}
.sl-footer-bento .sl-social-subtle {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent) !important;
}
.sl-footer-bento.sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-bento .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg) !important;
    border-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
}
.sl-footer-bento .sl-btn-primary:hover,
.sl-footer-bento .sl-btn-primary:focus-visible,
.sl-footer-bento .sl-btn-primary:active {
    background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    box-shadow: 0 4px 12px color-mix(in srgb, var(--smartlearn-primary) 30%, transparent) !important;
}

.sl-footer-bento .sl-bento-card { transition: transform 0.3s ease, border-color 0.3s ease; }
.sl-footer-bento .sl-hover-card:hover { transform: translateY(-5px); border-color: var(--smartlearn-primary) !important; }
.sl-footer-bento .sl-footer-link { transition: color 0.2s ease; font-weight: 500; position: relative; }
.sl-footer-bento .sl-footer-link:hover,
.sl-footer-bento .sl-footer-link:focus-visible { color: var(--smartlearn-primary) !important; }
.sl-footer-bento nav[aria-label="Learn"] .sl-footer-link::after,
.sl-footer-bento nav[aria-label="Support"] .sl-footer-link::after {
    content: "";
    width: 0.45em;
    height: 0.45em;
    border-inline-end: 2px solid var(--smartlearn-primary);
    border-top: 2px solid var(--smartlearn-primary);
    transform: translateX(-8px) rotate(45deg);
    opacity: 0;
    transition: opacity 0.2s ease, transform 0.2s ease;
}
[dir="rtl"] .sl-footer-bento nav[aria-label="Learn"] .sl-footer-link::after,
[dir="rtl"] .sl-footer-bento nav[aria-label="Support"] .sl-footer-link::after {
    transform: translateX(8px) rotate(-135deg);
}
.sl-footer-bento nav[aria-label="Learn"] .sl-footer-link:hover::after,
.sl-footer-bento nav[aria-label="Learn"] .sl-footer-link:focus-visible::after,
.sl-footer-bento nav[aria-label="Support"] .sl-footer-link:hover::after,
.sl-footer-bento nav[aria-label="Support"] .sl-footer-link:focus-visible::after {
    opacity: 1;
    transform: translateX(0) rotate(45deg);
}
[dir="rtl"] .sl-footer-bento nav[aria-label="Learn"] .sl-footer-link:hover::after,
[dir="rtl"] .sl-footer-bento nav[aria-label="Learn"] .sl-footer-link:focus-visible::after,
[dir="rtl"] .sl-footer-bento nav[aria-label="Support"] .sl-footer-link:hover::after,
[dir="rtl"] .sl-footer-bento nav[aria-label="Support"] .sl-footer-link:focus-visible::after {
    transform: translateX(0) rotate(-135deg);
}
.sl-footer-bento .sl-social-btn {
    width: 48px; height: 48px;
    transition: background-color 0.2s ease, color 0.2s ease, transform 0.2s ease;
}
.sl-footer-bento .sl-social-btn:hover,
.sl-footer-bento .sl-social-btn:focus-visible {
    background-color: var(--smartlearn-btn-bg) !important;
    color: var(--smartlearn-btn-text, #ffffff) !important;
    transform: scale(1.08);
}
.sl-footer-bento a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-bento .sl-bento-card,
    .sl-footer-bento .sl-footer-link,
    .sl-footer-bento .sl-footer-link::after,
    .sl-footer-bento .sl-social-btn,
    .sl-footer-bento .sl-btn-primary { transition: none; }
    .sl-footer-bento .sl-hover-card:hover,
    .sl-footer-bento .sl-social-btn:hover,
    .sl-footer-bento .sl-social-btn:focus-visible { transform: none; }
}
